{
  "summary": "Decision-7 is the narrow successor to decision-6: it preserves the accepted V1C local privilege-separated Authorization Ledger architecture and corrects only the mandatory matrix defect by providing 17 independently represented NO answers.",
  "payload": {
    "decision": {
      "candidate": "decision-7",
      "relationship": "Narrow successor to decision-6; preserves its substantive architecture without redesign.",
      "architectureOnly": true,
      "implementationAuthorized": false,
      "closedCandidatesNotReused": [
        "sha256:9bc6b4c3c63ffa02563d936557bfaced13e6f6251f7c0084bbd3abc01805a063",
        "sha256:c5d16bea3806ff0d10b7e092f8d2240d14d68b9461aeb44c206bf7fcb2fafb90"
      ]
    },
    "daemonAndOsIdentity": {
      "daemon": "authledgerd",
      "osIdentity": "mihver-ledger",
      "requirements": "Run authledgerd exclusively as the dedicated mihver-ledger OS identity. Models, Publication Broker, Night Runner, Authorization Loop, shells, Git, network tools and provider CLIs never receive this identity, ADMIN credentials, ADMIN descriptors or exact-UID ADMIN authorization. authledgerd alone owns and mutates privileged ledger state and performs no external execution effect."
    },
    "socketSplit": {
      "adminSocket": "A distinct Unix-domain ADMIN socket exposing only privileged trust-registry mutation, evidence import, grant issuance/revocation where supported, stopEpoch increment and bounded ADMIN reads.",
      "clientSocket": "A distinct Unix-domain CLIENT socket exposing only non-administrative ledger queries and dormant authorization/consume-once API surface. It cannot register Council trust, modify UID policy, import trust anchors, issue R3 grants or mutate stopEpoch.",
      "boundary": "Socket ownership, mode and group provide REACHABILITY ONLY. Every accepted connection is authenticated from kernel-supplied SO_PEERCRED UID, and each RPC is authorized for that exact UID against a root-owned policy appropriate to its socket and operation."
    },
    "privilegedStateStore": {
      "technology": "SQLite with WAL",
      "ownership": "Owned by mihver-ledger in a directory inaccessible for mutation by model-facing identities; root owns the authorization policy and trust-policy material.",
      "contents": [
        "global stopEpoch register",
        "admin_operation_journal",
        "CouncilEpochRegistry",
        "trusted evidence and AuthorizationGrant records",
        "consume-once state",
        "transactional audit records"
      ],
      "durability": "SQLite durability settings must make COMMIT the authoritative boundary. State is recovered from the persistent store after restart; no in-memory reconstruction is trusted."
    },
    "stopEpochDomain": {
      "minimum": 0,
      "maximum": 9007199254740991,
      "definition": "Number.MAX_SAFE_INTEGER = 2^53 - 1",
      "storage": "SQLite INTEGER with CHECK(stopEpoch >= 0 AND stopEpoch <= 9007199254740991).",
      "serialization": "Canonical JSON number only; no BigInt, unsigned-64 claim, floating-point approximation or wraparound.",
      "mutationRules": "The normal ADMIN API supports increment only, never decrement or reset. Increment at the maximum fails closed with STOP_EPOCH_EXHAUSTED."
    },
    "adminIncrementRequest": {
      "adminOperationId": "A caller-created, opaque, bounded, high-entropy UUIDv4/128-bit-equivalent string identifying exactly one logical ADMIN mutation. It is created before first transmission and reused verbatim for exact retries. It is neither a credential nor an actor identity and never affects authentication or authorization.",
      "expectedStopEpoch": "The caller's observed current epoch and the compare-and-set precondition for the increment."
    },
    "adminOperationJournal": {
      "table": "admin_operation_journal",
      "minimumFields": [
        "authenticatedPeerUid",
        "operationKind",
        "adminOperationId",
        "requestHash",
        "resultCode",
        "resultStopEpoch",
        "createdAt"
      ],
      "uniqueKey": [
        "authenticatedPeerUid",
        "operationKind",
        "adminOperationId"
      ],
      "location": "The same privileged SQLite transactional store as stopEpoch and audit state.",
      "durability": "Persistent and authoritative; never implemented as an in-memory retry cache."
    },
    "requestHashBinding": {
      "algorithm": "SHA-256 over deterministic canonical JSON",
      "domainSeparator": "MIHVER/AUTHLEDGERD/ADMIN/INCREMENT_STOP_EPOCH/REQUEST/V1C\u0000",
      "boundFields": [
        "authenticatedPeerUid",
        "operationKind",
        "adminOperationId",
        "expectedStopEpoch"
      ],
      "rule": "The authenticatedPeerUid is taken from SO_PEERCRED, not request text. Reuse of the same unique operation identity with different canonical request content fails closed with IDEMPOTENCY_KEY_REUSE, performs no mutation and does not return the stored result."
    },
    "exactIncrementTransaction": [
      "Authenticate the ADMIN connection using its kernel-supplied SO_PEERCRED UID.",
      "Authorize that exact UID against the root-owned exact-UID ADMIN allowlist; fail closed if the policy ownership, mode or format is invalid.",
      "Validate operationKind, adminOperationId, expectedStopEpoch and all canonical request constraints, then compute requestHash.",
      "BEGIN IMMEDIATE.",
      "Look up the unique key (authenticatedPeerUid, INCREMENT_STOP_EPOCH, adminOperationId).",
      "If an entry exists and its requestHash differs, roll back and return IDEMPOTENCY_KEY_REUSE without mutation and without returning the stored result.",
      "If an entry exists and its requestHash matches, return its previously committed resultStopEpoch and resultCode with no mutation and no second audit mutation event.",
      "Otherwise read the authoritative current stopEpoch.",
      "If expectedStopEpoch differs from current stopEpoch, roll back and return STALE_EXPECTED_STOP_EPOCH with no mutation.",
      "If current stopEpoch equals 9007199254740991, roll back and return STOP_EPOCH_EXHAUSTED with no mutation.",
      "Set next = current stopEpoch + 1 and write stopEpoch = next.",
      "Insert the successful journal result and append the audit mutation event whose actor is the authenticatedPeerUid.",
      "COMMIT the stopEpoch write, journal insert and audit append in one atomic commit boundary.",
      "Return next only after successful COMMIT."
    ],
    "lostAckTraceA": {
      "trace": "Current stopEpoch is N. ADMIN sends operation X with expectedStopEpoch N. The server atomically commits N+1, X's journal entry and the audit event, but the ACK is lost. The caller retries X with the same authenticated UID, operation kind, adminOperationId and expectedStopEpoch N, producing the same requestHash. The stored requestHash proves it is the exact request; the journal returns the previously committed N+1 with no mutation and no second audit mutation event. The epoch never reaches N+2."
    },
    "lostAckTraceB": {
      "trace": "Current stopEpoch is N. Operation X atomically commits N+1, its journal entry and audit event, but the ACK is lost and the caller loses X. The caller creates new logical operation Y while still supplying expectedStopEpoch N. Y has a new adminOperationId, so journal replay does not recognize it; the authoritative epoch is already N+1, so expected-epoch CAS fails with STALE_EXPECTED_STOP_EPOCH. No mutation occurs and the epoch never reaches N+2. Both durable journal replay and expected-epoch CAS are mandatory."
    },
    "concurrencyAndCrashSemantics": [
      {
        "case": 1,
        "semantics": "Two concurrent identical X requests cause at most one mutation; serialization and the journal make both callers converge on the same committed result."
      },
      {
        "case": 2,
        "semantics": "Different operation IDs X and Y both carrying expectedStopEpoch N cause at most one commit of N+1; the other fails STALE_EXPECTED_STOP_EPOCH, with no N+2."
      },
      {
        "case": 3,
        "semantics": "A crash before COMMIT commits none of the epoch write, journal entry or audit event."
      },
      {
        "case": 4,
        "semantics": "A crash after COMMIT but before ACK leaves epoch, journal and audit durable; an exact retry returns the stored result."
      },
      {
        "case": 5,
        "semantics": "After restart, the persistent journal and stopEpoch remain authoritative; no in-memory reconstruction is trusted."
      },
      {
        "case": 6,
        "semantics": "After an ambiguous response, the caller must resolve it through exact replay or the bounded result lookup and must never perform a blind second increment."
      }
    ],
    "operationResultLookup": {
      "choice": "OPTION A",
      "rpc": "getAdminOperationResult(operationKind, adminOperationId)",
      "rules": "Available only on the ADMIN socket, authenticated using the same SO_PEERCRED UID. The lookup key is scoped to that authenticated UID so callers can read only their own operations. It is strictly read-only, cannot mutate stopEpoch or the journal, and grants no additional authority."
    },
    "uidAuthenticationAuthorizationBoundary": {
      "reachability": "Socket ownership, mode and group are reachability controls only.",
      "authentication": "The service obtains the authenticated identity exclusively as the kernel-supplied SO_PEERCRED UID.",
      "authorization": "A root-owned, non-model-writable exact-UID allowlist authorizes each ADMIN operation. Wrong ownership, unsafe mode, malformed content or unknown policy data causes fail-closed startup or request rejection.",
      "callerText": "Caller-supplied uid, actor, approverUid, identity or similar text never overrides or supplements the kernel identity in any RPC.",
      "auditActor": "Always derived from authenticatedPeerUid."
    },
    "trustRegistryAndEvidenceImportBoundary": {
      "registry": "A privileged CouncilEpochRegistry whose mutations are ADMIN-only and authorized by exact SO_PEERCRED UID.",
      "trustBinding": "Each accepted CouncilConfig is exactly bound to its registered trust anchor and epoch. No model-writable CouncilConfig or other artifact can self-establish trust, silently replace a trust anchor or roll it back.",
      "import": "Canonical evidence import occurs only across the privileged ADMIN boundary. authledgerd independently parses and revalidates all model-writable artifacts rather than trusting caller-supplied hash-shaped strings.",
      "requiredValidation": [
        "canonical evidence parsing",
        "DecisionRecord recordHash verification",
        "CouncilQuorumProof verification wherever authorization policy requires it",
        "contextHash binding",
        "repositoryHead binding",
        "decisionRequestId binding",
        "taskId binding",
        "candidateHash binding"
      ],
      "failure": "Malformed, unknown, untrusted, mismatched, replacement or rollback evidence fails closed."
    },
    "authorizationGrantIssuance": {
      "issuer": "Only authledgerd may issue an R3 AuthorizationGrant, following an ADMIN request from an exact-UID-authorized privileged approver and successful independent validation against the trusted CouncilEpochRegistry and evidence.",
      "exactBindings": [
        "grantId",
        "AuthorizationEnvelope hash",
        "DecisionRecord recordHash",
        "candidateHash",
        "decisionRequestId",
        "taskId",
        "contextHash",
        "repositoryHead",
        "allowedScope",
        "prohibitedEffects",
        "stopEpochAtIssuance",
        "authenticatedApproverUid",
        "issuedAt",
        "issuance identity",
        "expiry state where supported",
        "revocation state where supported"
      ],
      "identityRule": "authenticatedApproverUid comes only from SO_PEERCRED. Free-text approver identity cannot authorize. Claude and Codex model identities never become privileged approver identities and never hold ADMIN capability or credentials.",
      "epochRule": "A grant whose stopEpochAtIssuance is less than the current global stopEpoch is void."
    },
    "consumeOnceSemantics": {
      "status": "DORMANT in V1C",
      "consumeIdentity": "A persistent unique consume key exactly binding grantId and AuthorizationEnvelope hash, with the grant's allowedScope, prohibitedEffects and stopEpochAtIssuance revalidated against the authoritative grant and current stopEpoch.",
      "transaction": "Under one privileged SQLite write transaction, validate the grant and current epoch, check the unique consume key, insert the consumed record and append the audit event, then COMMIT atomically.",
      "duplicates": "The first valid consume may transition the grant to consumed. Duplicate or concurrent consumes serialize on the unique consume key; at most one commits, and all later attempts return the deterministic already-consumed result recorded for that key without authorizing another effect.",
      "crashBeforeCommit": "Neither consume state nor its audit event is committed; a retry may perform the single valid consume.",
      "crashAfterCommit": "Consume state and audit are durable; a retry deterministically returns the stored already-consumed result and cannot consume again.",
      "v1cRestriction": "The ledger may contain this dormant state and API surface, but no V1C production component is connected to use ALLOW_ONCE for an execution effect."
    },
    "v1cExitGate": {
      "zeroProductionEffectConsumers": true,
      "publicationBrokerConsumesAllowOnce": false,
      "nightRunnerConsumesAllowOnce": false,
      "authorizationLoopConsumesAllowOnce": false,
      "shellEffectIntegration": false,
      "gitEffectIntegration": false,
      "networkEffectIntegration": false,
      "providerCliEffectIntegration": false,
      "authledgerdPerformsExternalEffects": false,
      "executionGatewayImplemented": false,
      "policySatisfiedCanCauseEffect": false,
      "allowOnceCanCauseEffect": false,
      "boundary": "Publication Broker remains structurally separate. V1D requires a separate gated decision before any production consumer or execution gateway may exist."
    },
    "yesNoMatrix": [
      {
        "id": "Q01",
        "question": "CAN CLAUDE ISSUE AN R3 AUTHORIZATIONGRANT?",
        "answer": "NO"
      },
      {
        "id": "Q02",
        "question": "CAN CODEX ISSUE AN R3 AUTHORIZATIONGRANT?",
        "answer": "NO"
      },
      {
        "id": "Q03",
        "question": "CAN CLAUDE MODIFY ADMIN UID POLICY?",
        "answer": "NO"
      },
      {
        "id": "Q04",
        "question": "CAN CODEX MODIFY ADMIN UID POLICY?",
        "answer": "NO"
      },
      {
        "id": "Q05",
        "question": "CAN CALLER-SUPPLIED UID BECOME AUTHORITATIVE?",
        "answer": "NO"
      },
      {
        "id": "Q06",
        "question": "CAN CLIENT SOCKET REGISTER COUNCIL TRUST?",
        "answer": "NO"
      },
      {
        "id": "Q07",
        "question": "CAN MODEL-WRITABLE COUNCILCONFIG SELF-ESTABLISH TRUST?",
        "answer": "NO"
      },
      {
        "id": "Q08",
        "question": "CAN CLAUDE INCREMENT STOPEPOCH?",
        "answer": "NO"
      },
      {
        "id": "Q09",
        "question": "CAN CODEX INCREMENT STOPEPOCH?",
        "answer": "NO"
      },
      {
        "id": "Q10",
        "question": "CAN NORMAL ADMIN API DECREMENT/RESET STOPEPOCH?",
        "answer": "NO"
      },
      {
        "id": "Q11",
        "question": "CAN A LOST ACK + SAME OPERATION ID INCREMENT TWICE?",
        "answer": "NO"
      },
      {
        "id": "Q12",
        "question": "CAN A LOST ACK + NEW OPERATION ID + STALE EXPECTED EPOCH INCREMENT TWICE?",
        "answer": "NO"
      },
      {
        "id": "Q13",
        "question": "CAN IDEMPOTENCY KEY REUSE WITH DIFFERENT REQUEST CONTENT SUCCEED?",
        "answer": "NO"
      },
      {
        "id": "Q14",
        "question": "CAN POLICY_SATISFIED CAUSE AN EFFECT?",
        "answer": "NO"
      },
      {
        "id": "Q15",
        "question": "CAN ALLOW_ONCE CAUSE AN EFFECT DURING V1C?",
        "answer": "NO"
      },
      {
        "id": "Q16",
        "question": "CAN BROKER/NIGHT RUNNER/AUTHORIZATION LOOP CONSUME PRODUCTION ALLOW_ONCE?",
        "answer": "NO"
      },
      {
        "id": "Q17",
        "question": "DOES V1C IMPLEMENT EXECUTION GATEWAY?",
        "answer": "NO"
      }
    ]
  }
}
